import json, pathlib
base = pathlib.Path("/home/hatch/workspace/divination/benchmark/phase3/runs/round48")
outdir = base / "predictions"
outdir.mkdir(parents=True, exist_ok=True)
batches = json.loads((base/"batches.json").read_text(encoding="utf-8"))
ids = batches["B13"]
assert len(ids)==20, len(ids)

P = {}
def add(cid, pred, basis, conf, cm, ru, dis, reason):
    P[cid] = {"case_id": cid, "prediction_text": pred, "basis": basis, "confidence": conf,
              "trigger": {"changed_main": cm, "reserve_used": ru, "disputed": dis, "reason": reason}}

