assert set(P.keys())==set(ids), (set(ids)-set(P.keys()))
for cid in ids:
    p=P[cid]
    assert p["case_id"]==cid
    assert set(p.keys())=={"case_id","prediction_text","basis","confidence","trigger"}
    assert isinstance(p["confidence"],(int,float)) and 0<=p["confidence"]<=1
    assert set(p["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
    (outdir/f"{cid}.json").write_text(json.dumps(p,ensure_ascii=False,indent=1),encoding="utf-8")

# 回读校验
n=0; cm=ru=dis=0
for cid in ids:
    q=json.loads((outdir/f"{cid}.json").read_text(encoding="utf-8"))
    assert q["case_id"]==cid and q["prediction_text"] and q["basis"]
    assert set(q["trigger"].keys())=={"changed_main","reserve_used","disputed","reason"}
    cm+=q["trigger"]["changed_main"]; ru+=q["trigger"]["reserve_used"]; dis+=q["trigger"]["disputed"]; n+=1
assert n==len(ids)==20
print(f"OK written={n} changed_main={cm} reserve_used={ru} disputed={dis}")
